function stripFocal(value: string) { return value.trim().replace(/\s*mm$/i, '').replace(/[^0-9.,]/g, ''); }
function stripAperture(value: string) { return value.trim().replace(/^ƒ?f?\s*\/?/i, '').replace(/[^0-9.,]/g, ''); }
function stripShutter(value: string) { return value.trim().replace(/\s*s$/i, '').replace(/[^0-9/.,]/g, ''); }
function stripIso(value: string) { return value.trim().replace(/^iso\s*/i, '').replace(/[^0-9]/gi, ''); }
function buildLines(data: Metadata) { const lines: string[] = []; if (data.camera.trim()) lines.push(data.camera.trim()); if (data.lens.trim()) lines.push(data.lens.trim()); const capture = [stripFocal(data.focal) ? `${stripFocal(data.focal)}mm` : '', stripAperture(data.aperture) ? `ƒ${stripAperture(data.aperture)}` : '', stripShutter(data.shutter) ? `${stripShutter(data.shutter)}s` : '', stripIso(data.iso) ? `ISO${stripIso(data.iso)}` : ''].filter(Boolean); if (capture.length) lines.push(capture.join(' ')); return lines; }
function formatBytes(bytes: number) { return bytes < 1048576 ? `${Math.round(bytes / 1024)} KB` : `${(bytes / 1048576).toFixed(1)} MB`; }
function safeFileName(value: string) { return value.replace(/\.[^/.]+$/, '').replace(/[^a-zA-Z0-9ğüşöçıİĞÜŞÖÇ_-]+/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '') || 'kompozisyon'; }
function readPhoto(file: File): Promise<Photo> { return new Promise((resolve, reject) => { const reader = new FileReader(); reader.onerror = () => reject(new Error(`${file.name} okunamadı.`)); reader.onload = () => { const dataUrl = String(reader.result); const image = new Image(); image.onerror = () => reject(new Error(`${file.name} görüntü olarak açılamadı.`)); image.onload = () => resolve({ id: `${file.name}-${file.size}-${file.lastModified}-${Math.random()}`, name: file.name, dataUrl, width: image.naturalWidth, height: image.naturalHeight, size: file.size, metadata: { ...emptyMetadata }, exifAvailable: false }); image.src = dataUrl; }; reader.readAsDataURL(file); }); }

