  useEffect(() => { localStorage.setItem('ig-language-v2', language); }, [language]);
  useEffect(() => { localStorage.setItem('ig-camera-user-choices-v2', JSON.stringify(cameraChoices)); }, [cameraChoices]);
  useEffect(() => { localStorage.setItem('ig-lens-user-choices-v2', JSON.stringify(lensChoices)); }, [lensChoices]);
  const notify = (message: string, path?: string, autoHide = false) => { if (toastTimerRef.current) window.clearTimeout(toastTimerRef.current); setToast(message); setExportPath(path ?? ''); setToastAutoHide(autoHide); if (autoHide) toastTimerRef.current = window.setTimeout(() => { setToast(''); setExportPath(''); setToastAutoHide(false); }, 5000); };
  const openExportFolder = async () => { if (!exportPath) return; try { await revealItemInDir(exportPath); } catch (error) { notify(error instanceof Error ? error.message : 'Finder açılamadı.', exportPath); } };
